                throw ConstraintException::ofError('not-null', ['user'], [null]);
            }
            $user = new UserRef(uid: $rawUser);
            $rawLoginProvider = $row['login_provider'] ?? null;
            if (null === $rawLoginProvider) {
                throw ConstraintException::ofError('not-null', ['loginProvider'], [null]);
            }
            $loginProvider = new TenantLoginProviderRef(uid: $rawLoginProvider);
            $subject = $row['subject'] ?? null;
            if (null === $subject) {
                throw ConstraintException::ofError('not-null', ['subject'], [null]);
            }
            $createdAt = $row['created_at'] ? new \DateTimeImmutable($row['created_at']) : null;
            $version = $row['version'] ?? null;
            return new UserFederatedIdentity(
                uid: $uid,
                user: $user,
                loginProvider: $loginProvider,
                subject: $subject,
                createdAt: $createdAt,
